-- 213: Original BrillaPrep WASSCE BrillaPrep transitional Sculpture beta content blueprint questions, part 1.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_213_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_213_guard;
INSERT INTO _migration_213_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_001' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_1' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In the study of traditional West African sculpture, what does animism most accurately describe?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A carving method in which every figure is made from a single log","B. A belief that spiritual agency or essence may inhabit people, animals, natural features or crafted objects","C. A style rule requiring all human figures to use naturalistic proportions","D. The use of animal shapes only as decoration without spiritual meaning"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Animism is a belief framework rather than a single visual style. In context, a sculpted figure, mask or object may mediate relationships among people, ancestors, spirits and the natural world. Therefore the correct answer is B: A belief that spiritual agency or essence may inhabit people, animals, natural features or crafted objects.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_001' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_213_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_002' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_1' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How can animist belief influence the form and use of a traditional West African sculpture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The sculpture becomes meaningful only when displayed as an unsigned gallery object","B. Material, symbols and form may be selected for an object intended to embody, address or mediate spiritual relationships","C. The maker chooses durable material solely to increase its market price","D. The artist must copy the visible appearance of the subject with anatomical accuracy"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Cultural interpretation links appearance to purpose and context. Symbolic materials, emphasis, attachments, placement and performance can help an object serve as a focus or mediator of spiritual and communal relationships. Therefore the correct answer is B: Material, symbols and form may be selected for an object intended to embody, address or mediate spiritual relationships.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_002' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_213_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_003' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_1' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the most responsible way to interpret a West African ritual sculpture whose original community context is uncertain?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. State the limits of the evidence and consult reliable provenance, community knowledge and contextual scholarship","B. Use formal resemblance to a better-documented regional style as enough evidence to assign the same ritual function","C. Read an enlarged head and frontal gaze as universal proof that the figure represents an ancestor","D. Adopt the earliest museum category as the community’s original name and use because it predates later scholarship"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Responsible interpretation avoids presenting speculation as fact. Provenance, maker or community knowledge, documented use and reputable scholarship should be compared, with uncertainty clearly acknowledged. Therefore the correct answer is A: State the limits of the evidence and consult reliable provenance, community knowledge and contextual scholarship.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_003' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_213_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_004' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_1' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which feature is strongly associated with Classical Greek sculptures of athletes?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Figures defined mainly by attached ritual materials that activate a shrine","B. Bodies reduced to geometric signs with no reference to muscular structure","C. Rigid frontal figures whose limbs never suggest weight transfer","D. Idealised anatomical proportion combined with observed balance, movement and controlled pose"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Classical Greek athletic sculpture joined observation with idealisation. Proportion, musculature, contrapposto and implied action presented the trained body as both physically credible and culturally exemplary. Therefore the correct answer is D: Idealised anatomical proportion combined with observed balance, movement and controlled pose.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_004' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_001', 'topic_was_sculpture_b004_1', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'In the study of traditional West African sculpture, what does animism most accurately describe?', 'multiple_choice', NULL, '["A. A carving method in which every figure is made from a single log","B. A belief that spiritual agency or essence may inhabit people, animals, natural features or crafted objects","C. A style rule requiring all human figures to use naturalistic proportions","D. The use of animal shapes only as decoration without spiritual meaning"]', 'B', 'Animism is a belief framework rather than a single visual style. In context, a sculpted figure, mask or object may mediate relationships among people, ancestors, spirits and the natural world. Therefore the correct answer is B: A belief that spiritual agency or essence may inhabit people, animals, natural features or crafted objects.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_1', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_002', 'topic_was_sculpture_b004_1', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'How can animist belief influence the form and use of a traditional West African sculpture?', 'multiple_choice', NULL, '["A. The sculpture becomes meaningful only when displayed as an unsigned gallery object","B. Material, symbols and form may be selected for an object intended to embody, address or mediate spiritual relationships","C. The maker chooses durable material solely to increase its market price","D. The artist must copy the visible appearance of the subject with anatomical accuracy"]', 'B', 'Cultural interpretation links appearance to purpose and context. Symbolic materials, emphasis, attachments, placement and performance can help an object serve as a focus or mediator of spiritual and communal relationships. Therefore the correct answer is B: Material, symbols and form may be selected for an object intended to embody, address or mediate spiritual relationships.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_1', 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_003', 'topic_was_sculpture_b004_1', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'What is the most responsible way to interpret a West African ritual sculpture whose original community context is uncertain?', 'multiple_choice', NULL, '["A. State the limits of the evidence and consult reliable provenance, community knowledge and contextual scholarship","B. Use formal resemblance to a better-documented regional style as enough evidence to assign the same ritual function","C. Read an enlarged head and frontal gaze as universal proof that the figure represents an ancestor","D. Adopt the earliest museum category as the community’s original name and use because it predates later scholarship"]', 'A', 'Responsible interpretation avoids presenting speculation as fact. Provenance, maker or community knowledge, documented use and reputable scholarship should be compared, with uncertainty clearly acknowledged. Therefore the correct answer is A: State the limits of the evidence and consult reliable provenance, community knowledge and contextual scholarship.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_1', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_004', 'topic_was_sculpture_b004_1', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Which feature is strongly associated with Classical Greek sculptures of athletes?', 'multiple_choice', NULL, '["A. Figures defined mainly by attached ritual materials that activate a shrine","B. Bodies reduced to geometric signs with no reference to muscular structure","C. Rigid frontal figures whose limbs never suggest weight transfer","D. Idealised anatomical proportion combined with observed balance, movement and controlled pose"]', 'D', 'Classical Greek athletic sculpture joined observation with idealisation. Proportion, musculature, contrapposto and implied action presented the trained body as both physically credible and culturally exemplary. Therefore the correct answer is D: Idealised anatomical proportion combined with observed balance, movement and controlled pose.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_1', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_sculpture_b004_001', 'q_was_sculpture_b004_002', 'q_was_sculpture_b004_003', 'q_was_sculpture_b004_004');
